import { expect, test } from "bun:test";
import { runOutLabel, windowPace, worstPace } from "../apps/client/src/lib/providers/pace.ts";

const DAY = 86_400_000;
const now = Date.UTC(2026, 9, 3, 12);
const weekly = (used: number, resetInDays: number) => ({
	name: "weekly",
	usedPercent: used,
	resetAt: now + resetInDays * DAY,
});

test("fast weekly window runs out before reset", () => {
	// 4 days elapsed, 80% used -> 100% after 1 more day, reset in 3 days.
	const pace = windowPace(weekly(80, 3), now);
	expect(pace).not.toBeNull();
	expect(pace?.runsOutAt).toBeCloseTo(now + DAY, -3);
});

test("on-pace weekly window has no warning", () => {
	expect(windowPace(weekly(40, 3), now)).toBeNull();
});

test("session windows and young windows are skipped", () => {
	expect(windowPace({ name: "5h", usedPercent: 90, resetAt: now + 3600_000 }, now)).toBeNull();
	// 0.5 days elapsed (<10%): too early to judge.
	expect(windowPace(weekly(60, 6.5), now)).toBeNull();
});

test("worstPace picks the earliest exhaustion", () => {
	const hit = worstPace([weekly(40, 3), weekly(90, 3)], now);
	expect(hit?.window.usedPercent).toBe(90);
});

test("dailyBudget splits what is left over the remaining days", async () => {
	const { dailyBudget, budgetLabel } = await import("../apps/client/src/lib/providers/pace.ts");
	// 20% left, 3 days to reset -> 6%/day (rounded down).
	const budget = dailyBudget(weekly(80, 3), now);
	expect(budget?.perDay).toBe(6);
	expect(budgetLabel(budget!)).toBe("max 6%/day");
	// Under a day left: today's cap is what today already used plus the whole remainder.
	expect(budgetLabel(dailyBudget(weekly(80, 0.5), now, 9)!)).toBe("max 29%/day");
	// A spent window has nothing to spread: no guide line, even on the last day.
	expect(dailyBudget(weekly(100, 0.5), now, 5)).toBeNull();
	expect(dailyBudget(weekly(100, 3), now)).toBeNull();
	expect(dailyBudget({ name: "weekly", usedPercent: 50 }, now)).toBeNull();
});

test("cycleStrip gives quiet days an empty slot and marks today", async () => {
	const { cycleStrip } = await import("../apps/client/src/lib/providers/card-format.ts");
	const local = new Date(2026, 9, 3, 12).getTime();
	const resetAt = new Date(2026, 9, 6, 12).getTime();
	const strip = cycleStrip(
		[
			{ day: "2026-10-02", usedPercent: 12.4 },
			{ day: "2026-10-03", usedPercent: 0 },
		],
		7 * DAY,
		resetAt,
		local,
	);
	// A 7-day cycle keeps 7 slots: the trailing partial day would repeat the
	// first weekday (Sep 29 and Oct 6 are both Tuesdays).
	expect(strip.map((d) => d.day)).toEqual([
		"2026-09-29",
		"2026-09-30",
		"2026-10-01",
		"2026-10-02",
		"2026-10-03",
		"2026-10-04",
		"2026-10-05",
	]);
	expect(strip[3]).toMatchObject({ pct: 12, today: false, future: false });
	expect(strip[4]).toMatchObject({ pct: 0, today: true });
	expect(strip[5]).toMatchObject({ pct: null, future: true });
	expect(strip[0].pct).toBeNull();
	expect(strip.filter((d) => d.reset).map((d) => d.day)).toEqual(["2026-10-05"]);
});

test("cycleStrip keeps one weekday per day for a Monday-to-Monday week", async () => {
	const { cycleStrip } = await import("../apps/client/src/lib/providers/card-format.ts");
	// OpenCode Go: reset Mon 09:00, so the 7-day window touches eight calendar
	// days and the strip must not show a second Monday.
	const now = new Date(2026, 9, 16, 22).getTime();
	const resetAt = new Date(2026, 9, 19, 9).getTime();
	const strip = cycleStrip([], 7 * DAY, resetAt, now);
	const weekdays = strip.map((d) => new Date(`${d.day}T12:00`).toLocaleDateString("en-US", { weekday: "short" }));
	expect(strip).toHaveLength(7);
	expect(new Set(weekdays).size).toBe(7);
	expect(weekdays).toEqual(["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]);
});

test("cycleStrip ignores a few seconds of reset jitter around midnight", async () => {
	const { cycleStrip } = await import("../apps/client/src/lib/providers/card-format.ts");
	const local = new Date(2026, 9, 9, 12).getTime();
	const midnight = new Date(2026, 9, 14).getTime();
	expect(cycleStrip([], 7 * DAY, midnight - 5_000, local)).toHaveLength(7);
	expect(cycleStrip([], 7 * DAY, midnight + 5_000, local)).toHaveLength(7);
});

test("runOutLabel names the time of day like the account's usage screen", () => {
	const now = new Date(2026, 9, 16, 22).getTime(); // Friday 22:00 local
	// A weekday projection keeps the short weekday and its part.
	expect(runOutLabel(new Date(2026, 9, 20, 21, 30).getTime(), now)).toBe("Tue night");
	expect(runOutLabel(new Date(2026, 9, 20, 9).getTime(), now)).toBe("Tue morning");
	expect(runOutLabel(new Date(2026, 9, 20, 15).getTime(), now)).toBe("Tue afternoon");
	expect(runOutLabel(new Date(2026, 9, 20, 19).getTime(), now)).toBe("Tue evening");
	// Same day and next day read as tonight / tomorrow.
	expect(runOutLabel(new Date(2026, 9, 16, 23).getTime(), now)).toBe("tonight");
	expect(runOutLabel(new Date(2026, 9, 16, 16).getTime(), now)).toBe("this afternoon");
	expect(runOutLabel(new Date(2026, 9, 17, 8).getTime(), now)).toBe("tomorrow morning");
	expect(runOutLabel(new Date(2026, 9, 17, 23).getTime(), now)).toBe("tomorrow night");
	// 02:00 still belongs to tonight, not tomorrow night.
	expect(runOutLabel(new Date(2026, 9, 17, 2).getTime(), now)).toBe("tonight");
});

test("ticket formatters date the expiry and start the D-day a week out", async () => {
	const { ticketExpiry, ticketDday } = await import("../apps/client/src/lib/providers/card-format.ts");
	const now = new Date(2026, 9, 16, 22).getTime();
	const expires = new Date(2026, 9, 23, 1).getTime(); // 7 days and 3h out
	expect(ticketExpiry(expires, now)).toBe("Oct 23");
	expect(ticketDday(expires, now)).toBe("D-7");
	// The board sends epoch seconds, like every other reset timestamp.
	expect(ticketExpiry(Math.floor(expires / 1000), now)).toBe("Oct 23");
	expect(ticketDday(Math.floor(expires / 1000), now)).toBe("D-7");
	expect(ticketDday(new Date(2026, 9, 30).getTime(), now)).toBe("");
	expect(ticketDday(now - 1, now)).toBe("D-day");
	// Inside the last 72 hours the hours left count down instead.
	expect(ticketDday(now + 5 * 3_600_000 - 60_000, now)).toBe("5h left");
	expect(ticketDday(now + 60_000, now)).toBe("1h left");
	expect(ticketDday(now + 25 * 3_600_000, now)).toBe("25h left");
	expect(ticketDday(now + 72 * 3_600_000 - 1, now)).toBe("72h left");
	// From 72 hours out, D-N counts calendar days: Oct 19 22:00 is D-3.
	expect(ticketDday(now + 72 * 3_600_000, now)).toBe("D-3");
	// A ticket without an expiry (i64::MAX through JSON) has no date line; JSON
	// keeps i64::MAX as `2 ** 63`, since the literal itself is not exact.
	expect(ticketExpiry(2 ** 63, now)).toBe("");
	expect(ticketExpiry(new Date(2027, 0, 2).getTime(), now)).toBe("Jan 2, 2027");
});

test("spendStrip is the calendar month, one slot a day, quiet days empty", async () => {
	const { spendStrip } = await import("../apps/client/src/lib/providers/card-format.ts");
	const days = [
		{ day: "2026-10-01", cents: 100 },
		{ day: "2026-10-03", cents: 250 },
		{ day: "2026-10-18", cents: 49 },
		{ day: "2026-09-30", cents: 999 },
	];
	const strip = spendStrip(days, Date.UTC(2026, 9, 18, 12));
	// October has 31 days; a monthly basis does not shorten to the tracked days.
	expect(strip).toHaveLength(31);
	expect(strip[0]).toEqual({ day: "2026-10-01", cents: 100, today: false, future: false });
	expect(strip[1]?.cents).toBeNull();
	expect(strip[2]?.cents).toBe(250);
	expect(strip[17]?.today).toBe(true);
	expect(strip[17]?.cents).toBe(49);
	expect(strip[18]?.future).toBe(true);
	// A day from another month is not a slot here.
	expect(strip.some((d) => d.day === "2026-09-30")).toBe(false);
});

test("spendStrip follows the calendar across a month boundary", async () => {
	const { spendStrip } = await import("../apps/client/src/lib/providers/card-format.ts");
	const strip = spendStrip([{ day: "2026-11-02", cents: 10 }], Date.UTC(2026, 10, 2, 12));
	expect(strip).toHaveLength(30);
	expect(strip[0]?.day).toBe("2026-11-01");
	expect(strip[1]?.cents).toBe(10);
	expect(strip[1]?.today).toBe(true);
});

test("prepaidPerDayCents spreads the balance over the rest of the month", async () => {
	const { prepaidPerDayCents, spendStrip } = await import("../apps/client/src/lib/providers/card-format.ts");
	// 19 Oct: the month still has 19..31, so 13 days to spend on.
	const strip = spendStrip([{ day: "2026-10-18", cents: 49 }], Date.UTC(2026, 9, 19, 12));
	expect(prepaidPerDayCents(2843, strip)).toBeCloseTo(2843 / 13, 6);
	// Last day of the month: the whole balance belongs to today.
	const last = spendStrip([], Date.UTC(2026, 9, 31, 12));
	expect(prepaidPerDayCents(1000, last)).toBe(1000);
	// Nothing left, nothing tracked, or a month with no today: no line.
	expect(prepaidPerDayCents(0, strip)).toBeNull();
	expect(prepaidPerDayCents(null, strip)).toBeNull();
	expect(
		prepaidPerDayCents(
			500,
			strip.map(() => ({ today: false })),
		),
	).toBeNull();
});

test("a prepaid chart opens on the week around today and a drag widens it", async () => {
	const { clampSpan, SPAN_DEFAULT, SPAN_MIN, spendStrip, zoomedSpendStrip } =
		await import("../apps/client/src/lib/providers/card-format.ts");
	// 19 October: a month of slots, seven of them still to come.
	const now = Date.UTC(2026, 9, 19, 12);
	const strip = spendStrip([{ day: "2026-10-18", cents: 49 }], now);
	// The default is one week, three days either side of today, and it is also
	// the narrowest a drag can close in to.
	expect(SPAN_DEFAULT).toBe(7);
	expect(SPAN_MIN).toBe(7);
	const around = zoomedSpendStrip(strip, SPAN_DEFAULT);
	expect(around.map((d) => d.day.slice(8))).toEqual(["16", "17", "18", "19", "20", "21", "22"]);
	expect(around.filter((d) => d.today)).toHaveLength(1);
	expect(around.filter((d) => d.future)).toHaveLength(3);
	expect(clampSpan(3, 31)).toBe(7);
	// A window that would run off the end of the month slides back inside it.
	const atEnd = spendStrip([], Date.UTC(2026, 9, 29, 12));
	expect(zoomedSpendStrip(atEnd, SPAN_DEFAULT).at(-1)?.day).toBe("2026-10-31");
	expect(zoomedSpendStrip(atEnd, SPAN_DEFAULT)).toHaveLength(SPAN_DEFAULT);
	// Widest still ends on the last day of the month, narrowest on the week.
	expect(zoomedSpendStrip(strip, 31)).toHaveLength(31);
	expect(zoomedSpendStrip(strip, 1)).toHaveLength(7);
	// Two days into the month there is no history to widen into: the window
	// starts on the first even when today is centred on it.
	const young = spendStrip([], Date.UTC(2026, 9, 2, 12));
	expect(zoomedSpendStrip(young, 7).map((d) => d.day.slice(8))).toEqual(["01", "02", "03", "04", "05", "06", "07"]);
});

test("clampSpan keeps the zoom inside a week and the month", async () => {
	const { clampSpan, spanLevels, stepSpan } = await import("../apps/client/src/lib/providers/card-format.ts");
	// Above the minimum, inside the days that have happened, and never past 31.
	expect(clampSpan(7, 19)).toBe(7);
	expect(clampSpan(2, 19)).toBe(7);
	expect(clampSpan(40, 19)).toBe(19);
	expect(clampSpan(40, 31)).toBe(31);
	// A month younger than the minimum shows what it has.
	expect(clampSpan(7, 2)).toBe(2);
	expect(clampSpan(0, 0)).toBe(1);
	// A drag steps between a week, a fortnight and the month, never a day at a time.
	expect(spanLevels(31)).toEqual([7, 14, 31]);
	expect(spanLevels(28)).toEqual([7, 14, 28]);
	expect(stepSpan(7, 1, 31)).toBe(14);
	expect(stepSpan(7, 2, 31)).toBe(31);
	expect(stepSpan(7, 5, 31)).toBe(31);
	expect(stepSpan(31, -1, 31)).toBe(14);
	expect(stepSpan(14, -3, 31)).toBe(7);
});

test("ticket history rows name the verdict, the local time and who spent it", async () => {
	const { ticketUseLabel } = await import("../apps/client/src/lib/providers/card-format.ts");
