export type ProviderHistory = Record<string, Record<string, WindowHistory>>;

export type Board = {
	monthlyUsd: number;
	yearlyUsd: number;
	/** Already in the user's saved order; providers it does not name follow in catalog order. */
	providers: Provider[];
