	order: string[];
	history?: ProviderHistory;
	spend?: ProviderSpend;
	/** The server spends a reset ticket on its own in its last five minutes. */
	autoReset: boolean;
	auth: {
		openai: boolean;
		commandcode: boolean;
		opencodeGo: boolean;
		grok: boolean;
		lithosai: boolean;
		openrouter: boolean;
		openrouterManagement: boolean;
		claude: boolean;
	};
};

