edits.newText:
export type TicketKind = { scope?: string; model?: string };

function ticketKind(ticket: TicketKind): string {
	return ticket.scope === "model" && ticket.model ? ticket.model : ticket.model && ticket.scope === "model" ? ticket.model : "Full";
}

/** Name of a reset ticket: `Fable reset` for a model reset, `Full reset` otherwise. */
export function ticketName(ticket: TicketKind): string {
	return `${ticketKind(ticket)} reset`;
}

/** What spending the ticket does, in words. */
export function ticketEffect(ticket: TicketKind): string {
	const kind = ticketKind(ticket);
	if (kind !== "Full") return `Resets the ${kind} allowance`;
	return "Resets weekly usage now";
}

export type TicketLike = TicketKind & { id?: string; expiresAt?: number; resetsLeft?: number };

/** Tickets still spendable, soonest expiry first; lapsed (or spent) tickets are dropped. */
export function liveTickets<T extends TicketLike>(tickets: readonly T[], now: number): T[] {
	return tickets
		.filter((t) => {
			if (t.resetsLeft != null && t.resetsLeft <= 0) return false;
			const ms = resetAtMs(t.expiresAt);
			if (ms == null) return true;
			if (Number.isNaN(new Date(ms).getTime())) return false;
			return ms > now;
		})
		.sort((a, b) => (resetAtMs(a.expiresAt) ?? Number.POSITIVE_INFINITY) - (resetAtMs(b.expiresAt) ?? Number.POSITIVE_INFINITY));
}

/** The soonest live ticket that clears weekly usage, if any; model resets never drive the weekly chart. */
export function weeklyTicket<T extends TicketLike>(tickets: readonly T[], now: number): T | undefined {
	return liveTickets(tickets, now).find((t) => ticketKind(t) === "Full");
}

/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: { at: number; result: string; source: string; scope?: string; model?: string }): {
	verb: string;
	day: string;
	clock: string;
	source: string | null;
	kind: string;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" }),
		source: use.result === "expired" ? null : use.source,
		kind: ticketKind(use),
	};
}

/** One ticket history row: `Used Oct 23 00:55 · Full reset · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string; scope?: string; model?: string }): string {
	const { verb, day, clock, source, kind } = ticketUseParts(use);
	return source ? `${verb} ${day} ${clock} · ${kind} reset · ${source}` : `${verb} ${day} ${clock} · ${kind} reset`;
}

